def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    # Pieces are 2x2 squares (color 1) or three-cell L shapes.
    pieces = []
    for r in range(h):
        for c in range(w):
            sq = {(r+i, c+j) for i in range(2) for j in range(2)}
            if sq <= cells:
                pieces.append((sq, 1))
            for missing in range(4):
                block = {(r+i, c+j) for i in range(2) for j in range(2)}
                block.remove((r + missing//2, c + missing%2))
                # Missing top-left -> 2, bottom-left -> 3, top-right -> 4.
                color = {0: 2, 2: 3, 1: 4, 3: 1}[missing]
                if block <= cells:
                    pieces.append((block, color))

    bycell = {p: [] for p in cells}
    for piece in pieces:
        for p in piece[0]:
            bycell[p].append(piece)

    def solve(left):
        if not left:
            return []
        p = min(left, key=lambda x: sum(piece[0] <= left for piece in bycell[x]))
        for shape, color in bycell[p]:
            if shape <= left:
                result = solve(left - shape)
                if result is not None:
                    return [(shape, color)] + result
        return None

    tiling = solve(cells)
    out = [[0] * w for _ in range(h)]
    if tiling:
        for shape, color in tiling:
            for r, c in shape:
                out[r][c] = color
    return out
